const first = items[0]?.json || {};
      const incomingSubject = first.incoming_subject || '';
      const incomingBody = first.incoming_body_text || '';
      const incomingSender = first.incoming_sender || '';

      const similarEmails = items.map((item, index) => {
        const j = item.json;
        return `Email ${index + 1}:
Sujet: ${j.subject || ''}
Contenu: ${j.body_text || ''}
Similarité: ${typeof j.similarity === 'number' ? j.similarity.toFixed(4) : j.similarity}`;
      }).join('

');

      const prompt = `EMAIL REÇU
Sujet: ${incomingSubject}
Expéditeur: ${incomingSender}
Contenu: ${incomingBody}

EMAILS SIMILAIRES
${similarEmails}

CONSIGNE
Tu es un assistant chargé de rédiger une réponse email professionnelle en français.
Utilise les emails similaires comme contexte.
N'invente pas d'informations absentes du contexte.
Si le contexte est insuffisant, réponds de manière prudente et générale.
Retourne uniquement le texte de la réponse email.`;

      return [{ json: { prompt } }];
